324	pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
325	    package
326	        .publish_to
327	        .iter()
328	        .any(|target| !matches!(target, callisto_model::PublishTarget::None))
329	}
330	
331	/// The workspace package with this exact release identity.
332	pub(crate) fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
333	    workspace: &'w Workspace<'_, R, D>,
334	    id: &ReleasePackageId,
335	) -> Option<&'w Package> {
336	    // By release identity, not name: a dual-manifest package's npm name can differ from its id.
337	    workspace
338	        .graph
339	        .packages()
340	        .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
341	}
342	
343	/// The fixed and linked groups a release package belongs to, per config.
344	fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
345	    workspace: &Workspace<'_, R, D>,
346	    id: &ReleasePackageId,
347	) -> Vec<(&'static str, callisto_model::GroupName)> {
348	    let Some(package) = workspace_package(workspace, id) else {
349	        return Vec::new();
350	    };
351	    let groups = &workspace.config.groups;
352	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
353	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
354	    // `member` keys are already canonical (`GroupTable::resolve` resolved
355	    // them through `IdentityIndex::resolve`), so exact equality is correct
356	    // here -- `PackageId::matches` would treat a Bare member key as an
357	    // ecosystem wildcard and could match a same-named package elsewhere.
358	    fixed
359	        .chain(linked)
360	        .filter(|(_, member, _)| **member == package.id)
361	        .map(|(kind, _, group)| (kind, group.clone()))
362	        .collect()
363	}
364	
365	/// Verifies the release roster a merged release commit claims, against a
366	/// release-decision file committed alongside it at `decision_path`.
367	///
368	/// This is intentionally *not* a second computation of changeset, fixed-group,
369	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
370	/// (via [`derive_release_decision`]) already computed that once, correctly,
371	/// when the release PR was generated -- and `callisto version --emit-decision`
372	/// commits its exact output alongside the manifest and changelog edits.
373	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
374	/// the kind of duplicated logic that drifts: an earlier version of this
375	/// function did just that, understood only a direct changeset match, and
376	/// rejected every real release in this repository once a fixed-group cascade
377	/// (a case its reimplementation never learned) touched an unnamed sibling.
378	///
379	/// Instead, this function reads the committed decision back and confirms the
380	/// commit's actual diff matches it exactly -- no more, no less.
381	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
382	/// entries don't match its content digest, so a hand-edited or corrupted
383	/// decision file fails before this function's own diff cross-check runs.
384	///
385	/// The caller must check out the exact merge commit in detached HEAD state
386	/// before creating an intent. GitHub-specific PR/approval provenance belongs
387	/// in the workflow boundary; this graph function verifies the local,
388	/// provider-neutral commit delta only.
389	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
390	    workspace: &Workspace<'_, R, D>,
391	    release_commit: &CommitSha,
392	    decision_path: &std::path::Path,
393	) -> Result<ReleaseDecisionV1, GraphError> {
394	    let (parent, changed) = commit_delta(workspace, release_commit)?;
395	    let decision_path_str = normalized_git_path(decision_path)?;
396	    require_version_commit_shape(workspace, release_commit, &changed, &decision_path_str)?;
397	    let decision = read_committed_decision(workspace, release_commit, decision_path, &decision_path_str)?;
398	    require_manifests_match_decision(workspace, release_commit, &parent, &changed, &decision)?;
399	    Ok(decision)
400	}
401	
402	/// The commit's parent and what the commit changed against it, as `(status, path)` pairs. Fails unless `HEAD` is the
403	/// release commit.
404	fn commit_delta<R: CommandRunner, D: DependencyResolver>(
405	    workspace: &Workspace<'_, R, D>,
406	    release_commit: &CommitSha,
407	) -> Result<(String, Vec<(String, String)>), GraphError> {
408	    let head_args = ["rev-parse", "HEAD"];
409	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
410	    let head =
411	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
412	    if &head != release_commit {
413	        return Err(GraphError::ReleaseCommitVerificationFailed {
414	            commit: release_commit.clone(),
415	            reason: CommitVerificationFailure::HeadMismatch,
416	        });
417	    }
418	
419	    let parent_ref = format!("{}^", release_commit.as_str());
420	    let parent_args = ["rev-parse", parent_ref.as_str()];
421	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
422	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
423	
424	    let diff_tree_args = [
425	        "diff-tree",
426	        "--no-commit-id",
427	        "--name-status",
428	        "-r",
429	        "--no-renames",
430	        parent.as_str(),
431	        release_commit.as_str(),
432	    ];
433	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
434	    let changed = parse_name_status(&changed, &diff_tree_args)?;
435	    Ok((parent, changed))
436	}
437	
438	/// The commit has the shape of a version commit: it wrote the decision, consumed a changeset, and touched only the
439	/// paths a version commit may touch.
440	fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
441	    workspace: &Workspace<'_, R, D>,
442	    release_commit: &CommitSha,
443	    changed: &[(String, String)],
444	    decision_path: &str,
445	) -> Result<(), GraphError> {
446	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
447	
448	    // The decision must be freshly authored as part of *this* commit, not a
449	    // stale leftover an earlier release already committed and this one never
450	    // touched -- otherwise a commit that changes nothing real could still
451	    // carry forward a prior, unrelated decision's authority.
452	    let decision_freshly_written = changed
453	        .iter()
454	        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
455	    if !decision_freshly_written {
456	        return Err(GraphError::ReleaseCommitVerificationFailed {
457	            commit: release_commit.clone(),
458	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
459	        });
460	    }
461	
462	    // A cheap, independent sanity check that this commit is a real version
463	    // application and not just a hand-crafted decision file: some real
464	    // changeset was actually consumed. The decision's own entries, not this
465	    // changeset's content, remain the sole authority verified below.
466	    let consumed_a_changeset = changed
467	        .iter()
468	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
469	    if !consumed_a_changeset {
470	        return Err(GraphError::ReleaseCommitVerificationFailed {
471	            commit: release_commit.clone(),
472	            reason: CommitVerificationFailure::NoChangesetConsumed,
473	        });
474	    }
475	
476	    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
477	    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
478	    // or where, under the cover of a bot-authored diff.
479	    let changelogs = workspace
480	        .graph
481	        .packages()
482	        .filter_map(|package| package.changelog.as_deref())
483	        .map(normalized_git_path)
484	        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
485	    for (_, path) in changed {
486	        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
487	            return Err(GraphError::ReleaseCommitVerificationFailed {
488	                commit: release_commit.clone(),
489	                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
490	            });
491	        }
492	    }
493	    Ok(())
494	}
495	
496	/// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
497	fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
498	    workspace: &Workspace<'_, R, D>,
499	    release_commit: &CommitSha,
500	    decision_path: &std::path::Path,
501	    decision_path_str: &str,
502	) -> Result<ReleaseDecisionV1, GraphError> {
503	    let decision_source = git_file(
504	        workspace.runner,
505	        &workspace.root,
506	        release_commit.as_str(),
507	        decision_path_str,
508	    )?;
509	    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
510	        path: decision_path.to_path_buf(),
511	        message: error.to_string(),
512	    })
513	}
514	
515	/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
516	/// no package the decision does not claim changed version.
517	fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
518	    workspace: &Workspace<'_, R, D>,
519	    release_commit: &CommitSha,
520	    parent: &str,
521	    changed: &[(String, String)],
522	    decision: &ReleaseDecisionV1,
523	) -> Result<(), GraphError> {
524	    let claimed = decision
525	        .entries
526	        .iter()
527	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
528	        .collect::<std::collections::BTreeMap<_, _>>();
529	
530	    let changed_paths = changed
531	        .iter()
532	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
533	        .collect::<std::collections::BTreeSet<_>>();
534	
535	    // Every canonical manifest path this workspace currently declares, in
536	    // the exact order `workspace.graph.packages()` and
537	    // `Package::canonical_manifests()` yield -- both are backed by ordered
538	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
539	    // the second traversal below visits the same (package, manifest) pairs
540	    // in the same order. That lets it zip the batched `before`/`after`
541	    // results back on by position instead of re-keying by path, which would
542	    // misbehave if two packages ever declared an identical manifest path.
543	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
544	        .graph
545	        .packages()
546	        .flat_map(Package::canonical_manifests)
547	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
548	        .collect::<Result<_, GraphError>>()?;
549	    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
550	    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
551	    for (path, _) in manifest_queries
552	        .iter()
553	        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
554	    {
555	        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
556	        {
557	            let candidate = normalized_git_path(&candidate)?;
558	            if !query_path_list.contains(&candidate) {
559	                query_path_list.push(candidate);
560	            }
561	        }
562	    }
563	    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();
564	
565	    // Exactly two `git cat-file --batch` subprocess invocations total (one
