fn derive_release_inputs_with<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: SourceIdentity,
    artifact_policy: Option<&ArtifactBuildPolicy>,
    remote: GitRemoteRequirement,
    diagnostics: &mut Vec<Diagnostic>,
) -> Result<DerivedReleaseInputs, GraphError> {
    if workspace
        .config
        .product_release
        .as_ref()
        .is_some_and(|release| release.forge_repository.is_none())
    {
        return Err(GraphError::ReleaseForgeRepositoryMissing);
    }
    let mut package_inputs = Vec::new();
    let Selection {
        selected,
            "release",
            "artifact-manifest",
            "--intent",
            intent.to_str().unwrap(),
            "--artifact-dir",
            artifacts.to_str().unwrap(),
            "--out",
            manifest.to_str().unwrap(),
        ],
    );
    assert!(create_manifest.status.success());
    let config = root.join("callisto.toml");
    let moved = fs::read_to_string(&config).unwrap().replace(
        "forge-repository = \"example/core-crate\"",
        "forge-repository = \"example/moved\"",
    );
    fs::write(&config, moved).unwrap();
    let receipt = external.path().join("release-receipt.json");
    let (bin, log, forge_marker, git_trace) = fake_publishers(external.path(), &release_commit, false);
    let out = execute_product(
        root,
        &intent,
        &manifest,
        &artifacts,
        &receipt,
        FakePublishers {
            bin: &bin,
            log: &log,
            forge_marker: &forge_marker,
            git_trace: &git_trace,
        },
    );
    let err = String::from_utf8_lossy(&out.stderr);
