547	fn add_tags(
548	    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
549	    package_ids: &BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
550	    owners: &Owners,
551	    source: &SourceIdentity,
552	    ops: &mut Ops,
553	) -> Result<(), GraphError> {
554	    let Ops {
555	        operations,
556	        prepared,
557	        index,
558	    } = ops;
559	
560	    for (id, (package, version)) in owned(selected, owners) {
561	        if !package
562	            .publish_to
563	            .iter()
564	            .any(|target| !matches!(target, PublishTarget::None))
565	        {
566	            continue;
567	        }
568	        let tag = ReleaseOperation::tag(
569	            id.clone(),
570	            version.clone(),
571	            index.tag_prerequisites(
572	                package_ids
573	                    .get(&package.id)
574	                    .map_or(std::slice::from_ref(id), Vec::as_slice),
575	            ),
576	        )?;
577	        let tag_name = package
578	            .tag_template
579	            .clone()
580	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
581	            .render(version);
582	        let target = match source {
583	            SourceIdentity::GitCommit { sha } => sha.clone(),
584	            SourceIdentity::HermeticContent { .. } => {
585	                return Err(GraphError::UnsupportedRelease {
586	                    feature: UnsupportedReleaseFeature::SourceIdentity,
587	                })
588	            }
589	        };
590	        prepared.insert(
591	            tag.id().clone(),
592	            PreparedOperation::Tag(TagOperation {
593	                annotation: format!("Release {tag_name}"),
594	                name: tag_name,
595	                target,
596	            }),
597	        );
598	        index.tag_by_package.insert(id.clone(), tag.id().clone());
599	        operations.insert(tag.id().clone(), tag);
600	    }
601	    Ok(())
602	}
